CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS volumes(id INTEGER PRIMARY KEY, root TEXT NOT NULL UNIQUE, label TEXT, fs TEXT, kind TEXT NOT NULL CHECK(kind IN ('local','network','cloud')), last_scan_id INTEGER);
CREATE TABLE IF NOT EXISTS scans(id INTEGER PRIMARY KEY, volume_id INTEGER REFERENCES volumes(id), root TEXT NOT NULL, started TEXT NOT NULL, finished TEXT, method TEXT CHECK(method IN ('mft','fallback','managed')), total_size INTEGER, file_count INTEGER, snapshot_path TEXT);
CREATE TABLE IF NOT EXISTS folder_snapshots(scan_id INTEGER NOT NULL REFERENCES scans(id) ON DELETE CASCADE, path_hash INTEGER NOT NULL, path TEXT NOT NULL, size INTEGER NOT NULL, file_count INTEGER NOT NULL, PRIMARY KEY(scan_id, path_hash));
CREATE TABLE IF NOT EXISTS rules(id TEXT PRIMARY KEY, json TEXT NOT NULL, source TEXT NOT NULL, priority INTEGER NOT NULL DEFAULT 500, enabled INTEGER NOT NULL DEFAULT 1, created TEXT NOT NULL, updated TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS decisions(id INTEGER PRIMARY KEY, ts TEXT NOT NULL, path TEXT NOT NULL, features_json TEXT NOT NULL, action TEXT NOT NULL CHECK(action IN ('keep','delete','never','always')), reason TEXT, origin TEXT NOT NULL CHECK(origin IN ('app','telegram','auto')));
CREATE TABLE IF NOT EXISTS rule_suggestions(id INTEGER PRIMARY KEY, rule_json TEXT NOT NULL, evidence_json TEXT NOT NULL, confidence REAL NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','rejected')), created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS watches(id INTEGER PRIMARY KEY, path TEXT NOT NULL, json TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, next_run TEXT);
CREATE TABLE IF NOT EXISTS job_runs(id INTEGER PRIMARY KEY, watch_id INTEGER, plan_id INTEGER, sync_id INTEGER, started TEXT NOT NULL, finished TEXT, status TEXT NOT NULL, freed_bytes INTEGER NOT NULL DEFAULT 0, summary_json TEXT);
CREATE TABLE IF NOT EXISTS actions_log(id INTEGER PRIMARY KEY, ts TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('recycle','delete','move','backup','sync','map')), items_json TEXT NOT NULL, bytes INTEGER NOT NULL DEFAULT 0, undo_token TEXT, origin TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cloud_accounts(id INTEGER PRIMARY KEY, provider TEXT NOT NULL, display_name TEXT NOT NULL, cred_ref TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS backup_plans(id INTEGER PRIMARY KEY, account_id INTEGER NOT NULL REFERENCES cloud_accounts(id), json TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, next_run TEXT);
CREATE TABLE IF NOT EXISTS backup_manifest(plan_id INTEGER NOT NULL REFERENCES backup_plans(id) ON DELETE CASCADE, local_path TEXT NOT NULL, size INTEGER NOT NULL, mtime TEXT NOT NULL, hash TEXT, remote_id TEXT, uploaded_at TEXT, PRIMARY KEY(plan_id, local_path));
CREATE TABLE IF NOT EXISTS network_shares(id INTEGER PRIMARY KEY, unc TEXT NOT NULL UNIQUE, letter TEXT, cred_ref TEXT, reconnect INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS sync_jobs(id INTEGER PRIMARY KEY, source TEXT NOT NULL, target TEXT NOT NULL, mode TEXT NOT NULL CHECK(mode IN ('mirror','copy','twoway')), json TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, next_run TEXT);
CREATE TABLE IF NOT EXISTS telegram(id INTEGER PRIMARY KEY CHECK(id = 1), chat_id INTEGER, cred_ref TEXT, paired_at TEXT, prefs_json TEXT);
CREATE TABLE IF NOT EXISTS pending_remote_actions(id INTEGER PRIMARY KEY, payload_json TEXT NOT NULL, expires_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending');
CREATE INDEX IF NOT EXISTS ix_decisions_path ON decisions(path);
CREATE INDEX IF NOT EXISTS ix_actions_ts ON actions_log(ts);
